// The Uzbek phrase book — the pages' sentences, keyed by their English.
//
// This file is loaded on demand by lib/i18n.jsx (`import()` once the language
// is known), so a reader in one language never downloads the other two. The
// English needs no book: it is the key. Every entry here must have its twin
// in i18n.ru.js — qa/round74-suite.mjs reads both and fails the gate when
// one book has a phrase the other has not, or when the code asks for a
// phrase that is in neither.
//
// Keep an entry on one line, four spaces in, `"English": "translation",` —
// that is the shape the suites read.
