    "the whole vocabulary, in six lines": "butun lugʻat olti qatorda",
    "A piece": "Ish",
    "One item of content, counted once — however many channels it goes out on and however many people touched it.": "Kontentning bitta birligi, bir marta sanaladi — necha kanalda chiqsa va unga necha kishi qoʻl ursa ham.",
    "It was published, dated by the day it went out on the Tashkent clock.": "U chiqarilgan; kun deb Toshkent vaqti boʻyicha chiqqan kuni olinadi.",
    "Its release day falls inside the window. That is the plan — the board’s own promise, not a number anybody types in.": "Chiqish kuni shu davrga tushadi. Reja shu — doskaning oʻz vaʼdasi, kimdir yozib qoʻygan raqam emas.",
    "It went out on or before its release day. A piece with no release day is neither on time nor late, and is counted separately.": "Oʻz chiqish kunida yoki undan oldin chiqqan. Chiqish kuni yoʻq ish na oʻz vaqtida, na kechikkan — u alohida sanaladi.",
    "A step": "Bosqich",
    "One person’s part of one piece: the shoot, the edit, the artwork, the release. Each has its own day and its own owner, and belongs to the window that day falls in.": "Bitta ishning bitta odam bajaradigan qismi: sʼyomka, montaj, dizayn, chiqish. Har birining oʻz muddati va oʻz masʼuli bor va u shu muddat tushgan davrga tegishli.",
    "Missed, and knock-on": "Oʻtkazib yuborilgan va zanjir boʻyicha",
    "A missed step finished after its day, or has not finished with the day gone. A knock-on step could only start after its own day had already gone, because the step before it handed over late — it is the same delay seen twice, so it is counted apart and charged to nobody.": "Oʻtkazib yuborilgan bosqich oʻz muddatidan keyin tugagan yoki muddat oʻtgani holda hali tugamagan. Zanjir boʻyicha bosqich esa oʻz muddati oʻtganidan keyingina boshlana olgan, chunki undan oldingisi kech topshirilgan — bu oʻsha kechikishning ikkinchi marta koʻrinishi, shuning uchun alohida sanaladi va hech kimga yozilmaydi.",
    "{n} days late": "{n} kun kechikib",
    "{n} days overdue": "{n} kun muddati oʻtgan",
    "re-promised": "muddat qayta vaʼda qilingan",
    "shoot day": "sʼyomka kuni",
    "{open} deadlines still to meet · {late} met late": "{open} muddat hali bajarilmagan · {late} tasi kechikib bajarilgan",
    "Every deadline on the board that has not been met, across the whole team.": "Doskadagi bajarilmagan barcha muddatlar, butun jamoa boʻyicha.",
    "Every deadline of yours that has not been met.": "Sizning bajarilmagan barcha muddatlaringiz.",
    "The report below counts a window at a time; this counts everything still outstanding.": "Quyidagi hisobot davr boʻyicha sanaydi; bu yerda esa hali bajarilmagan hamma narsa.",
    "pieces with a step past its day": "bosqichi muddatidan oʻtgan ishlar",
    "Behind schedule": "Muddatdan orqada",
    "What went out each month, and how much of it made its release day": "Har oyda nima chiqqani va shundan qanchasi oʻz chiqish kuniga ulgurgani",
    "{n} steps finished": "{n} bosqich tugatildi",
    "{n} pieces went out": "{n} ish chiqdi",
    "Steps finished": "Tugatilgan bosqichlar",
    "A step is one person’s part of a piece — filmed, edited, designed or published.": "Bosqich — bu ishning bitta odam bajargan qismi: suratga olindi, montaj qilindi, dizayn qilindi yoki chiqarildi.",
    "{n} went out": "{n} chiqdi",
    "{n} on time": "{n} oʻz vaqtida",
    "{n} planned": "{n} rejalashtirilgan",
    "What these numbers are standing on": "Bu raqamlar nimaga tayanadi",
    "Nothing is missing — every piece on the board carries what the reports need to read it.": "Hammasi joyida — doskadagi har bir ishda hisobotlar uchun kerak boʻlgan hamma narsa bor.",
    "Set {n} pieces to count as published on their own release days? Their statistics and their pay move with them, and each one keeps a line in its log saying what the day used to be.": "{n} ta ish oʻz chiqish kunida chiqqan deb hisoblansinmi? Ular bilan birga statistika va toʻlov ham siljiydi, har birining jurnalida esa avvalgi kun haqida yozuv qoladi.",
    "{n} corrected": "{n} tasi tuzatildi",
    "{n} marked published that day": "oʻsha kuni {n} tasi chiqarilgan deb belgilangan",
    "promised between {a} and {b}": "{a} va {b} orasida vaʼda qilingan",
    "{n} days after the day they were promised, in the middle": "mediana boʻyicha — vaʼda qilingan kundan {n} kun keyin",
    "Use each piece’s own release day as the day it went out": "Chiqqan kun sifatida har bir ishning oʻz chiqish kunini olish",
    "Correcting…": "Tuzatilmoqda…",
    "They went out on their days": "Ular oʻz kunlarida chiqqan",
    "and {n} more": "va yana {n} ta",
    "Read from the board as it stands on {day}": "{day} holatiga koʻra doskadan oʻqildi",
    "The board was caught up in batches": "Doska toʻp-toʻp bilan toʻldirilgan",
    "On these days a pile of pieces was marked published at once, days or weeks after the day each one was promised for. The posts almost certainly went out on time; the board only heard about it later — and every on-time figure counts the day the card moved.": "Bu kunlarda bir toʻda ish birdan chiqarilgan deb belgilangan — har birining vaʼda qilingan kunidan kun yoki hafta keyin. Postlar deyarli aniq oʻz vaqtida chiqqan, doska buni keyinroq bilgan, «oʻz vaqtida» degan har qanday raqam esa kartochka siljigan kunni sanaydi.",
    "Published with no release day": "Chiqish kunisiz chiqarilgan",
    "Nothing to compare the day it went out against, so these can be neither on time nor late. They sit outside every punctuality figure on the page.": "Chiqqan kunni solishtirishga narsa yoʻq, shuning uchun ular na oʻz vaqtida, na kechikkan. Ular sahifadagi barcha muddat raqamlaridan tashqarida qoladi.",
    "In Published, but not recorded as out": "«Chiqarilgan»da, lekin chiqqani yozilmagan",
    "The card sits in the final stage with no moment of going out on it, so no report counts it. Move it out and back in, or tick it done.": "Kartochka oxirgi bosqichda turibdi, lekin unda chiqqan payt yoʻq, shuning uchun uni hech bir hisobot sanamaydi. Uni chiqarib, qayta qoʻying yoki tayyor deb belgilang.",
    "Open with no day of any kind": "Ishda, birorta ham kunsiz",
    "No shoot day, no edit day, no release day. It cannot be late, cannot be planned for, and appears in no forecast — it is invisible to every number here.": "Na sʼyomka kuni, na montaj kuni, na chiqish kuni. U kechika olmaydi, rejaga kira olmaydi va hech qanday bashoratda koʻrinmaydi — bu yerdagi barcha raqamlar uchun u yoʻq.",
    "Filmed work with no editor": "Montajchisi yoʻq suratga olingan ish",
    "The edit has a deadline and nobody answering for it, so a missed edit lands on no one and the editing figures are short by exactly these.": "Montajning muddati bor, masʼuli yoʻq, shuning uchun oʻtkazib yuborilgan montaj hech kimga tushmaydi va montaj raqamlari aynan shularga kam.",
    "Overdue by more than a month": "Bir oydan koʻproq muddati oʻtgan",
    "Promised over thirty days ago and still not out. Either it is still coming and needs a real day, or it is not coming and should be closed — while it is neither, it counts against every month it touches.": "Oʻttiz kundan koʻproq oldin vaʼda qilingan, hali ham chiqmagan. Yo u hali chiqadi va unga haqiqiy kun kerak, yo chiqmaydi va uni yopish kerak — ikkisi ham boʻlmaguncha, u tegib turgan har bir oyni buzadi.",
    "Mark as not done": "Belgini olib tashlash",
    "Duplicate": "Nusxalash",
