    "One piece went out with nobody counting its views — this total is what has been counted, not what the month got.": "Bitta ish koʻrishlari sanalmasdan chiqdi — bu sanalganning yigʻindisi, butun oyniki emas.",
    "Not counted yet": "Hali sanalmagan",
