    "Then read the groups from 1 to 5. The top one matters most.": "Keyin guruhlarni 1 dan 5 gacha koʻring. Eng yuqoridagisi eng muhimi.",
    "Press a piece to open it. The week below shows what is filmed and what goes out.": "Materialni bosing — u ochiladi. Pastdagi hafta nima suratga olinishi va nima chiqishini koʻrsatadi.",
    "Start here": "Shu yerdan boshlang",
    "Why this one first:": "Nega avval shu:",
    "Start this task": "Shu vazifani boshlash",
    "After you press:": "Bosganingizdan keyin:",
    "the task opens with short steps. The last step is “{button}”.": "vazifa qisqa qadamlar bilan ochiladi. Oxirgi qadam — «{button}».",
    "It is the oldest late task you can start now — {late}. {name} is waiting for it.": "Bu hozir boshlash mumkin boʻlgan eng eski kechikkan vazifa ({late}). {name} uni kutyapti.",
    "{name} asked you to change something, and is waiting for it.": "{name} biror narsani tuzatishni soʻradi va kutyapti.",
    "{name} is waiting for your answer. It takes one tap.": "{name} javobingizni kutyapti. Bir marta bosish kifoya.",
    "Nothing is late. This is the next thing in your day: {when}.": "Kechikkan ish yoʻq. Bugungi navbatdagi ish shu: {when}.",
    "Nothing is late and today is clear. This is the next one: {when}.": "Kechikkan ish yoʻq, bugungi ishlar tugadi. Keyingisi: {when}.",
    "{name} sees your answer at once. If you say no, {name} finds another person.": "{name} javobingizni darhol koʻradi. Yoʻq desangiz, {name} boshqa odam topadi.",
    "The team": "Jamoa",
    "The crew": "Jamoa",
    "Your tasks, in the order to do them": "Vazifalaringiz — bajarish tartibida",
    "Oldest first": "Avval eng eskilari",
    "Answers first, then by the clock": "Avval javoblar, keyin vaqt boʻyicha",
    "Not for today": "Bugun uchun emas",
    "Done today": "Bugun bajarildi",
    "You handed these in": "Bularni topshirdingiz",
    "for {name}": "{name} uchun",
    "was due {day}": "muddati {day} edi",
    "until {day}": "muddat: {day}",
    "Answer needed": "Javob kerak",
    "Changes asked": "Tuzatish soʻralgan",
    "That is all here. The one task is the big card above.": "Bu yerda boshqa narsa yoʻq. Yagona vazifa — yuqoridagi katta kartochkada.",
    "All done, {name}": "Hammasi bajarildi, {name}",
    "Nothing is waiting for you. New work shows up here the moment someone gives it to you.": "Sizni hech narsa kutmayapti. Yangi ish sizga berilishi bilan shu yerda paydo boʻladi.",
    "Nothing is late. Keep going with today.": "Kechikkan ish yoʻq. Bugungi ishlarni davom ettiring.",
    "Nothing more is planned for today.": "Bugunga boshqa hech narsa rejalashtirilmagan.",
    "When you press the red button on a task, it moves here — and the next person gets it.": "Vazifadagi qizil tugmani bossangiz, u shu yerga oʻtadi — va keyingi odamga yetib boradi.",
    "Your pieces, the most pressing first": "Materiallaringiz — avval eng shoshilinchi",
    "Filming today": "Bugun suratga olinadi",
    "It happens at a set time, so it comes first. Check that the crew is coming.": "Suratga olish belgilangan vaqtda boʻladi, shuning uchun u birinchi. Jamoa kelishini tekshiring.",
    "Nothing is filmed today.": "Bugun suratga olish yoʻq.",
    "Pravka": "Tahrir",
    "Someone waits for your answer — or fixes what was asked.": "Kimdir javobingizni kutyapti — yoki soʻralgan narsani tuzatyapti.",
    "Nothing to check and nothing is being fixed.": "Tekshiradigan narsa yoʻq, hech narsa tuzatilmayapti.",
    "Check it": "Tekshiring",
    "An edit or artwork came in. Look and answer.": "Montaj yoki dizayn keldi. Koʻring va javob bering.",
    "Nothing to check. New edits and artwork land here.": "Tekshiradigan narsa yoʻq. Yangi montaj va dizaynlar shu yerga tushadi.",
    "Being fixed": "Tuzatilmoqda",
    "Changes were asked for. Nothing to press.": "Tuzatish soʻralgan. Hech narsa bosish kerak emas.",
    "Nothing is being fixed.": "Hech narsa tuzatilmayapti.",
    "Past its day. Remind the person who has it — or do your own step.": "Muddati oʻtdi. Vazifa kimda boʻlsa, unga eslating — yoki oʻz qadamingizni bajaring.",
    "Nothing is late.": "Kechikkan ish yoʻq.",
    "Your move": "Sizning navbatingiz",
    "The crew can’t start until you add your words.": "Siz tavsif qoʻshmaguningizcha jamoa ishni boshlay olmaydi.",
    "Nothing waits for your words.": "Tavsifingizni kutayotgan narsa yoʻq.",
    "Ready to publish": "Nashrga tayyor",
