    "Not good yet? Ask for changes — {name} fixes it.": "Hali yaxshi emasmi? Tuzatishni soʻrang — {name} tuzatadi.",
    "{name} finished the edit and waits for your answer. The piece can’t go on without it.": "{name} montajni tugatdi va javobingizni kutyapti. Javobsiz material oldinga yurmaydi.",
    "{name} finished the artwork and waits for your answer. The piece can’t go on without it.": "{name} dizaynni tugatdi va javobingizni kutyapti. Javobsiz material oldinga yurmaydi.",
    "It is planned to be filmed today, and it is not sent to the shoot yet.": "Suratga olish bugunga rejalashtirilgan, lekin vazifa hali suratga olishga yuborilmagan.",
    "It is late — {late} — and the next step is yours.": "Vazifa kechikdi ({late}), keyingi qadam sizda.",
