    "Step {n}: mark as done": "{n}-qadam: bajarildi deb belgilash",
    "Tap a number when that step is done.": "Qadam bajarilgach, raqamini bosing.",
    "The last step is the button just below.": "Oxirgi qadam — sal pastdagi tugma.",
    "Press “{button}”": "«{button}» tugmasini bosing",
    "The red button, just below.": "Qizil tugma, sal pastda.",
    "Read the script": "Ssenariyni oʻqing",
    "It is lower in this window. It says what to film.": "U shu oynaning pastida. Unda nimani suratga olish yozilgan.",
    "Film it": "Suratga oling",
    "Check the sound before you start.": "Boshlashdan oldin ovozni tekshiring.",
    "Paste the link to the footage, if you have one": "Videomaterial havolasi boʻlsa, uni qoʻying",
    "The box is just below. You can skip it — but the editor edits from these files.": "Maydon sal pastda. Oʻtkazib yuborsa boʻladi — lekin montajchi shu fayllardan montaj qiladi.",
    "It is lower in this window. It says what the video must look like.": "U shu oynaning pastida. Unda video qanday boʻlishi yozilgan.",
    "Open the footage and edit it": "Videomaterialni oching va montaj qiling",
    "The footage is under Files.": "Videomaterial «Fayllar» boʻlimida.",
    "Paste the link to your edit": "Montajingiz havolasini qoʻying",
    "The box is just below.": "Maydon sal pastda.",
    "It is lower in this window. It says what the picture must show.": "U shu oynaning pastida. Unda rasmda nima boʻlishi yozilgan.",
    "Draw it": "Chizing",
    "The examples are under Files.": "Namunalar «Fayllar» boʻlimida.",
    "Paste the link to your artwork": "Dizayningiz havolasini qoʻying",
