    "It is under Files. {name} made it.": "U «Fayllar» boʻlimida. Uni {name} tayyorlagan.",
    "It is under Files.": "U «Fayllar» boʻlimida.",
    "Is it what you asked for?": "Bu siz soʻragan narsami?",
