    "Press “Accept” — or “Ask for changes”": "«Qabul qilish»ni — yoki «Tuzatishni soʻrash»ni bosing",
    "The two buttons, just below.": "Ikki tugma, sal pastda.",
    "Fill in what is asked": "Soʻralgan narsalarni toʻldiring",
    "{n} things are asked. The boxes are just below.": "Toʻldirish kerak: {n} ta. Maydonlar sal pastda.",
    "Nothing is missing.": "Hammasi toʻldirilgan.",
    "Look at it one last time": "Oxirgi marta koʻrib chiqing",
