    "Paste the link to the post first. Then the button wakes up.": "Avval post havolasini qoʻying. Shunda tugma ishlaydi.",
    "Fill in the boxes above first. Then the button wakes up.": "Avval yuqoridagi maydonlarni toʻldiring. Shunda tugma ishlaydi.",
    "Write what must change first. Then the button wakes up.": "Avval nimani oʻzgartirish kerakligini yozing. Shunda tugma ishlaydi.",
    "{name} gets the new version and checks it again.": "{name} yangi versiyani oladi va yana tekshiradi.",
    "The new version goes back to be checked again.": "Yangi versiya yana tekshiruvga ketadi.",
    "The task moves to Editing. You edit it next — it comes back to your list as an edit.": "Vazifa «Montaj»ga oʻtadi. Uni oʻzingiz montaj qilasiz — u roʻyxatingizga montaj boʻlib qaytadi.",
    "{name} gets the footage and starts to edit it. You are done with this one.": "{name} videomaterialni oladi va montajni boshlaydi. Sizning ishingiz shu bilan tugaydi.",
    "The task moves on. {name} sees that it is filmed.": "Vazifa oldinga oʻtadi. {name} suratga olinganini koʻradi.",
    "{name} gets your edit. {name} watches it and takes it — or asks you to change something.": "{name} montajingizni oladi, koʻradi va qabul qiladi — yoki biror narsani tuzatishni soʻraydi.",
    "{name} gets your artwork. {name} looks at it and takes it — or asks you to change something.": "{name} dizayningizni oladi, koʻradi va qabul qiladi — yoki biror narsani tuzatishni soʻraydi.",
    "{name} asks: can you film it {when}?": "{name} soʻrayapti: {when} suratga ola olasizmi?",
    "{name} asks: can you finish the edit by {day}?": "{name} soʻrayapti: montajni shu kungacha topshira olasizmi — {day}?",
    "You can’t start yet.": "Hali boshlab boʻlmaydi.",
