    "The shoot has no day yet. When it has one, it shows here.": "Suratga olish kuni hali belgilanmagan. Belgilansa, shu yerda koʻrinadi.",
    "Watch it, then answer.": "Koʻring, keyin javob bering.",
    "Look at it, then answer.": "Koʻrib chiqing, keyin javob bering.",
    "What must change?": "Nimani oʻzgartirish kerak?",
    "For example: the music is too loud at 0:40. Make the name bigger.": "Masalan: 0:40 da musiqa juda baland. Ismni kattaroq qiling.",
    "Send to {name}": "Yuborish: {name}",
