    "It is late. You can remind {name}.": "Muddati oʻtdi. Eslatishingiz mumkin: {name}.",
    "It is late.": "Muddati oʻtdi.",
    "Name another person, or move the shoot to a new day — under “Edit the task” below.": "Boshqa odam tayinlang yoki suratga olishni boshqa kunga koʻchiring — pastdagi «Vazifani oʻzgartirish» orqali.",
