    "{name} was already reminded today": "{name}: bugun allaqachon eslatilgan",
    "Remind writes a line in this task’s comments. Only the person you remind gets a bell.": "«Eslatish» shu vazifa izohlariga bir satr yozadi. Bildirishnomani faqat siz eslatgan odam oladi.",
    "What is late can’t be started yet: the footage is not in.": "Kechikkan vazifani hali boshlab boʻlmaydi: videomaterial hali kelmagan.",
    "What is late can’t be started yet: it is not sent to you.": "Kechikkan vazifani hali boshlab boʻlmaydi: u sizga hali yuborilmagan.",
    "What is late can’t be started yet: it waits for somebody else.": "Kechikkan vazifani hali boshlab boʻlmaydi: u boshqa odamni kutyapti.",
    "So this is the first one you can do: {when}.": "Shuning uchun birinchi qila oladiganingiz shu: {when}.",
    "Pressed by mistake?": "Adashib bosdingizmi?",
    "You can take it back for {n} more seconds.": "Yana {n} soniya ichida qaytarish mumkin.",
    "You said you can’t make it.": "Siz ulgurmasligingizni aytdingiz.",
    "{name} moves the day or asks another person. Nothing for you to do until then.": "{name} kunni koʻchiradi yoki boshqa odamdan soʻraydi. Ungacha siz hech narsa qilishingiz shart emas.",
    "Can you make it after all?": "Baribir ulgurasizmi?",
    "Press “I can make it”. It comes back to your list with a number.": "«Ulguraman» tugmasini bosing. Vazifa roʻyxatingizga raqam bilan qaytadi.",
    "You said you can’t": "Siz rad etdingiz",
    "{name} has to answer": "endi {name} javob beradi",
    "One thing is asked. The box is just below.": "Bitta narsa soʻralyapti. Katak sal pastda.",
    "{n} / {limit} characters": "{n} / {limit} belgi",
    "Too long for {channel} — shorten it to {limit} characters.": "{channel} uchun juda uzun — {limit} belgigacha qisqartiring.",
    "A video or a picture?": "Video yoki rasm bormi?",
    "This post has a video or a picture": "Bu postda video yoki rasm bor",
    "An editor or a designer makes it first, as on Instagram.": "Avval uni montajchi yoki dizayner tayyorlaydi, Instagramdagidek.",
    "You write it and post it. Nobody films or designs.": "Siz yozasiz va joylaysiz. Hech kim suratga olmaydi va dizayn qilmaydi.",
    "Short posts": "Qisqa postlar",
    "Short written posts with a length limit — X, Threads, LinkedIn": "Uzunligi cheklangan qisqa matnli postlar — X, Threads, LinkedIn",
    "Head of {channel}": "{channel} rahbari",
    // TikTok and YouTube Shorts: one video, posted again (Reposts.jsx).
    "Posted again": "Qayta joylash",
    "This is «{title}» from {channel}, posted again here.": "Bu «{title}» ({channel}) — bu yerda qayta joylanadi.",
    "This is «{title}», posted again here.": "Bu «{title}» — bu yerda qayta joylanadi.",
    "The video to post": "Joylanadigan video",
    "The original has no video link yet — ask whoever edited it.": "Asl nusxada hali video havolasi yoʻq — montaj qilgan odamdan soʻrang.",
    "Open the original": "Asl nusxani ochish",
    "TikTok and Shorts": "TikTok va Shorts",
    "Also {channel}": "Yana {channel}",
    "When it is published: {name} gets a task for each one — the same video and caption, to post the next day.": "Eʼlon qilinganda: {name} har biri uchun vazifa oladi — oʻsha video va matn, ertasi kuni joylash uchun.",
    "Not ticked: it goes out on this channel only.": "Belgilanmagan: faqat shu kanalda chiqadi.",
    "When it is published, it also goes to {channels}.": "Eʼlon qilingach, yana shu yerlarga joylanadi: {channels}.",
    "It goes out on this channel only. Whoever runs it can add TikTok or Shorts.": "Faqat shu kanalda chiqadi. Vazifa egasi TikTok yoki Shorts qoʻshishi mumkin.",
    "It went out on this channel only — nothing was ticked before it was published.": "Faqat shu kanalda chiqdi — eʼlon qilinishidan oldin hech narsa belgilanmagan edi.",
    "Also on {channel}: {state}": "Yana {channel}: {state}",
    "published": "eʼlon qilindi",
    "waiting to be posted": "joylanishini kutmoqda",
    "Nobody is named to post it yet": "Uni joylash uchun hali hech kim tayinlanmagan",
    "{name} posts it by {day}": "{name} joylaydi, muddat: {day}",
    "{name} posts it": "{name} joylaydi",
    "See the post": "Postni koʻrish",
    "Its videos can also go to TikTok and Shorts": "Bu yerdagi videolarni TikTok va Shortsga ham joylash mumkin",
    "A video here gets two ticks, TikTok and Shorts. Ticked, publishing it gives somebody a task to post it there too.": "Bu yerdagi videoda ikkita belgi chiqadi — TikTok va Shorts. Belgilansa, eʼlon qilinganda kimdir uni u yerda ham joylash vazifasini oladi.",
    "Off: a video here goes out on this channel only.": "Oʻchirilgan: bu yerdagi video faqat shu kanalda chiqadi.",
    "Reposts": "Qayta joylashlar",
    "A finished video posted again — TikTok, YouTube Shorts. Nobody films or edits: it arrives ready and goes out.": "Tayyor video qayta joylanadi — TikTok, YouTube Shorts. Hech kim suratga olmaydi va montaj qilmaydi: tayyor holda keladi va chiqadi.",
    // The Ambassadors calendar (October 2026).
    "With editor": "Montajchida",
    "Waiting over 2 days": "2 kundan ortiq kutyapti",
    "New": "Yangi",
    "came in today": "bugun keldi",
