    "Book a shoot": "Syomka belgilash",
    "Name who edits": "Montajchini belgilash",
    "Ask for a cover": "Muqova soʻrash",
    "Minutes with the board open in front of somebody, and the buttons they pressed, per day. Below: every page and press by name since 14 October, to find where the board is hard to use — never what anybody typed.": "Doska kimningdir oldida ochiq turgan daqiqalar va bosilgan tugmalar — kunma-kun. Quyida — 14-oktabrdan beri har bir sahifa va bosish ism bilan, doskadan qayerda foydalanish noqulay ekanini topish uchun — lekin hech kim yozgan narsa emas.",
    "Loading the presses…": "Bosishlar yuklanmoqda…",
    "{n} presses on this page in {d} days": "Bu sahifada {d} kunda bosishlar: {n}",
    "on a button": "tugmaga",
    "on nothing pressable": "bosilmaydigan joyga",
    "Close the heatmap": "Issiqlik xaritasini yopish",
    "The report could not be read": "Hisobotni oʻqib boʻlmadi",
    "How the board is used": "Doskadan qanday foydalanilmoqda",
    "Nothing recorded yet. The first report appears after people have used the board for a while.": "Hali hech narsa yozilmagan. Birinchi hisobot doskadan biroz foydalanilgandan keyin paydo boʻladi.",
    "Which report": "Qaysi hisobot",
    "Weeks": "Haftalar",
