    "Someone": "Kimdir",
    "Every task opens in the same window, on every page. To change it, press Edit at the top.": "Har bir vazifa har qanday sahifada bir xil oynada ochiladi. Uni oʻzgartirish uchun yuqoridagi «Tahrirlash»ni bosing.",
    "A task starts with its deadline, then the reference, the files and the ТЗ (the arrow opens it in full).": "Vazifa muddatdan boshlanadi, keyin referens, fayllar va TZ (strelka uni toʻliq ochadi).",
    "The previous look is gone.": "Avvalgi koʻrinish olib tashlandi.",
    "Checks it": "Tekshiradi",
    "Your artwork waits for the edit. Then {name} checks both.": "Dizayningiz montajni kutadi. Keyin {name} ikkalasini tekshiradi.",
    "Artwork handed in — it waits for the edit": "Dizayn topshirildi — montajni kutadi",
    "The day has gone. {name} sets a new one.": "Bu kun oʻtib ketdi. {name} yangi kun belgilaydi.",
    "Pick the new day.": "Yangi kunni tanlang.",
    "Your own day: say why, and it moves at once.": "Bu sizning kuningiz: sababini yozing — u darhol koʻchadi.",
    "This day is promised — only an admin moves it, and only on a reason.": "Bu kun vaʼda qilingan — uni faqat admin va faqat sabab bilan koʻchiradi.",
    "This day is promised — only an admin moves it.": "Bu kun vaʼda qilingan — uni faqat admin koʻchiradi.",
    "Task saved — synced": "Vazifa saqlandi — sinxronlandi",
