    "the operator’s raw material — the editor’s source": "operatorning xom videosi — montajchi shundan montaj qiladi",
    "the editor’s finished edit": "montajchining tayyor montaji",
    "the designer’s finished artwork": "dizaynerning tayyor ishi",
    "What the designer works from: a reference and the ТЗ.": "Dizayner nimadan ishlaydi: referens va ТЗ.",
    "excused — handed over late": "uning aybi emas — kech topshirildi",
