    "Your shoots, edit and design deadlines and release days appear in Apple Calendar by themselves, and stay up to date when something moves on the board.": "Syomkalaringiz, montaj va dizayn muddatlari hamda chiqish kunlari Apple Calendarʼda oʻzi paydo boʻladi va doskada biror narsa oʻzgarsa yangilanadi.",
