    "Edit menu": "Menyuni oʻzgartirish",
    "Edit your menu": "Menyuingiz",
    "− sends a row to More, + brings it back, the dots drag it.": "− qatorni «Yana»ga oladi, + qaytaradi, nuqtalar sudraydi.",
    "Your phone’s bar": "Telefondagi panel",
    "Empty": "Boʻsh",
    "Now press a place below for slot {n}.": "Endi {n}-katak uchun pastdan joyni bosing.",
    "Press a slot, then a place.": "Katakni, keyin joyni bosing.",
    "On your menu": "Menyuingizda",
    "Put this menu back": "Menyuni avvalgi holiga qaytarish",
    "Send {name} to More": "«Yana»ga olish: {name}",
    "Bring {name} back to the menu": "Menyuga qaytarish: {name}",
    "Move {name}: drag, or the arrow keys": "Koʻchirish: {name} — sudrang yoki strelkalar bilan",
    "Slot {n}: {name}. Press, then a place, to change it": "{n}-katak: {name}. Almashtirish uchun bosing, keyin joyni tanlang",
    "Slot {n} is empty. Press, then a place": "{n}-katak boʻsh. Bosing, keyin joyni tanlang",
    "Files go straight into the piece’s Drive folder: drop them in the box, no link to paste.": "Fayllar toʻgʻridan-toʻgʻri vazifaning Drive papkasiga tushadi: ularni ramkaga tashlang, havola kerak emas.",
    "A press on a task opens the whole task. Its plan is at the side: press a name or a day to change it.": "Vazifani bossangiz, u toʻliq ochiladi. Reja yonda: oʻzgartirish uchun ism yoki kunni bosing.",
    "My Day: what to do now, and today’s shoots or edits beside it. The lists stand side by side.": "«Mening kunim»: hozir nima qilish kerak, yonida esa bugungi suratga olish yoki montajlar. Roʻyxatlar yonma-yon.",
    "The calendar and the menu: your channels are on the left. “Edit menu” chooses what stays and what goes under More.": "Kalendar va menyu: kanallaringiz chapda. «Menyuni oʻzgartirish» nima qolishini va nima «Yana»ga ketishini tanlaydi.",
    "Channels did not load. Retrying…": "Kanallar yuklanmadi. Yana urinib koʻramiz…",
    "Retry now": "Hozir qayta urinish",
    "You are on no channel yet. Ask the admin to add you to one.": "Siz hali birorta kanalga qoʻshilmagansiz. Admindan sizni qoʻshishini soʻrang.",
    "The menu is one list: every page is on it, nothing is under More. Your channels are in the middle.": "Menyu — bitta roʻyxat: hamma sahifalar unda, «Yana» ostida hech narsa yoʻq. Kanallaringiz oʻrtada.",
    "Settings is the gear beside your name at the foot of the menu. The tour is the question mark next to it.": "Sozlamalar — menyu pastida ismingiz yonidagi tishli gʻildirak. Koʻrsatmalar — uning yonidagi soʻroq belgisi.",
    "The phone’s bar has the calendar and your board; the rest is under More, which opens the same list.": "Telefon panelida kalendar va doskangiz; qolgani «Yana» ostida, u ham shu roʻyxatni ochadi.",
    "My Day is where you start every time. Every other page is on this one list; your channels are in the middle.": "«Mening kunim» — har safar shu yerdan boshlaysiz. Qolgan sahifalar shu roʻyxatda; kanallaringiz oʻrtada.",
    "The big card is the one thing to do first. Its button does the step; “Open the task” shows the whole piece.": "Katta karta — birinchi qilinadigan ish. Uning tugmasi qadamni bajaradi; «Vazifani ochish» vazifani toʻliq koʻrsatadi.",
    "Then the groups": "Keyin guruhlar",
    "Under the card, your pieces in the order they press: late first, then what is yours to move, then what is ready to publish.": "Karta ostida — vazifalaringiz shoshilinchlik tartibida: avval kechikkanlar, keyin sizning navbatingiz, keyin nashrga tayyorlari.",
    "A new idea": "Yangi gʻoya",
    "“New task” asks for a name and the idea. The channel decides the rest; the later questions wait until the piece moves on.": "«Yangi vazifa» nom va gʻoyani soʻraydi. Qolganini kanal hal qiladi; boshqa savollar vazifa oldinga yurguncha kutadi.",
    "The big card is the one thing to do first. Its button opens the task with your step ready — drop the file, press Send.": "Katta karta — birinchi qilinadigan ish. Uning tugmasi vazifani sizning qadamingiz bilan ochadi: faylni tashlang, «Yuborish»ni bosing.",
    "Yours, but not yet in your hands: a cut with no footage, a piece not sent on. Each wakes up by itself when its turn comes.": "Sizniki, lekin hali qoʻlingizda emas: materialsiz montaj, hali uzatilmagan vazifa. Har biri navbati kelganda oʻzi uygʻonadi.",
    "A row per person, the hours across: shoots are bars, posts are pins, lessons are hatched. Press a name’s count to see what they hold up.": "Har odamga bir qator, soatlar eniga: suratga olishlar — chiziqlar, nashrlar — belgilar, darslar — shtrix. Kim nimani ushlab turganini koʻrish uchun ism yonidagi sonni bosing.",
    "The deadlines": "Muddatlar",
    "What is past its day, what is due today and what needs editing now — folded under the timetable. Open a piece from any row.": "Muddati oʻtgan, bugungi va hozir montaj kerak boʻlganlar — jadval ostida yigʻilgan. Vazifani istalgan qatordan ochish mumkin.",
    "{name} is still planning it. When it is sent on, it moves into your list and the button appears here.": "{name} hali vazifani rejalashtirmoqda. U oldinga uzatilganda roʻyxatingizga tushadi, shu yerda tugma paydo boʻladi.",
    "The shoot is {when}. On that day the button appears here.": "Suratga olish {when}. Oʻsha kuni shu yerda tugma paydo boʻladi.",
    "Write what must change first. Then the button appears.": "Avval nimani oʻzgartirish kerakligini yozing. Keyin tugma paydo boʻladi.",
    "Paste the link first. Then the button appears.": "Avval havolani qoʻying. Keyin tugma paydo boʻladi.",
    "Drop the file first. Then the button appears.": "Avval faylni tashlang. Keyin tugma paydo boʻladi.",
    "Paste the link to the post first. Then the button appears.": "Avval nashr havolasini qoʻying. Keyin tugma paydo boʻladi.",
    "Fill in the boxes above first. Then the button appears.": "Avval yuqoridagi kataklarni toʻldiring. Keyin tugma paydo boʻladi.",
    "Discard the recording": "Yozuvni oʻchirish",
    "Throw it away and start again": "Tashlab, qaytadan yozish",
    "Stop recording": "Yozishni toʻxtatish",
    "Record a voice note": "Ovozli xabar yozish",
    "Say it instead of typing it": "Yozish oʻrniga aytib bering",
    "Pause the voice note": "Ovozli xabarni toʻxtatib turish",
    "Play the voice note": "Ovozli xabarni eshitish",
    "— pick a format —": "— shaklni tanlang —",
    "— pick a rubrika —": "— rukn tanlang —",
    "There is nothing here.": "Bu yerda hech narsa yoʻq.",
    "This is a placeholder, not a brief.": "Bu toʻldirgich, texnik topshiriq emas.",
    "Four words is not an instruction anybody can follow.": "Toʻrt soʻz — hech kim amal qila oladigan koʻrsatma emas.",
    "Short enough that whoever picks this up will have to ask.": "Shunchalik qisqaki, buni olgan odam soʻrashga majbur boʻladi.",
    "A link with no words around it does not say what to do with it.": "Yonida soʻz boʻlmagan havola u bilan nima qilishni aytmaydi.",
    "This looks like keyboard mash rather than a brief.": "Bu texnik topshiriqdan koʻra tasodifiy harflar yigʻindisiga oʻxshaydi.",
    "Your browser blocked the microphone — allow it in the address bar": "Brauzer mikrofonga ruxsat bermadi — manzil satrida ruxsat bering",
    "blocked": "ruxsat yoʻq",
    "https://… reference video or post": "https://… namuna uchun video yoki post",
    "reference": "namuna",
