    "Email": "Pochta",
    "+998 …, @telegram, email": "+998 …, @telegram, pochta",
    "e.g. $600 / 7 mln UZS": "masalan, $600 / 7 mln soʻm",
    "Handed over late — this was due": "Kech topshirildi — muddati edi",
    "Member — runs channels": "Muallif — kanallarni yuritadi",
    "Production crew — films, edits or designs": "Prodakshn — suratga oladi, montaj qiladi yoki chizadi",
    "**bold** · start a line with - for a bullet": "**qalin** · roʻyxat uchun qatorni - bilan boshlang",
    "On the card": "Kartada",
    "Bold (⌘B)": "Qalin (⌘B)",
    "Bold": "Qalin",
    "Bullet list": "Roʻyxat",
