    "link or where to look": "havola yoki qayerdan qarash",
    "The big card’s button opens the task with your step ready; “Open the task” shows the whole piece.": "Katta kartaning tugmasi vazifani sizning qadamingiz bilan ochadi; «Vazifani ochish» vazifani toʻliq koʻrsatadi.",
    "In the task a button appears when it can be pressed. Until then the line under the box says what is missing.": "Vazifada tugma bosish mumkin boʻlganda paydo boʻladi. Ungacha katak ostidagi qator nima yetishmasligini aytadi.",
    "A day is picked on a calendar card and reads the same everywhere: “Fri 6 Nov”.": "Kun kalendar kartasida tanlanadi va hamma joyda bir xil oʻqiladi: «jum, 6-noy».",
    // ---- S-05: the admin panel (20 Oct 2026) ----
    "Redirect URI on record with Google:": "Google tomonida yozilgan Redirect URI:",
    "Google Drive isn’t set up on the server yet — five minutes, once:": "Google Disk serverda hali sozlanmagan — besh daqiqa, bir marta:",
    "Signed in as the team’s Google account, open": "Jamoaning Google hisobi bilan kirib, oching:",
    "→ create a project →": "→ loyiha yarating →",
    "APIs & Services → Library": "API va xizmatlar → Kutubxona",
    "→ enable": "→ yoqing:",
    "OAuth consent screen": "OAuth rozilik oynasi",
    ": External, app name “SATashkent Dashboard”, add the scopes": ": External, ilova nomi «SATashkent Dashboard», ruxsat doiralarini qoʻshing:",
    "(uploads) and": "(yuklashlar) va",
    "(drop-in reads the three drop folders) — then": "(fayl qabuli uchta topshirish papkasini oʻqiydi) — keyin",
    "Publish app": "Ilovani nashr qilish",
    "(left in Testing, the connection expires after 7 days). Publishing asks for the home page": "(Testing rejimida qolsa, ulanish 7 kundan soʻng tugaydi). Nashr qilishda bosh sahifa manzili soʻraladi:",
    "and the privacy policy": "va maxfiylik siyosati:",
    "Credentials → Create credentials → OAuth client ID → Web application": "Hisob maʼlumotlari → Hisob maʼlumotlarini yaratish → OAuth mijoz ID → Veb-ilova",
    "Copy the client ID and secret into the repository secrets": "Mijoz ID va maxfiy kalitni repozitoriy sirlariga nusxalang:",
    "and": "va",
    "(GitHub → Settings → Secrets → Actions), then": "(GitHub → Settings → Secrets → Actions), keyin",
    "Come back here and press": "Bu yerga qayting va bosing:",
    "Checking the bridge…": "Koʻprik tekshirilmoqda…",
    "The bridge": "Koʻprik",
    "The bot isn’t configured. Put the @BotFather token into the repository secret": "Bot sozlanmagan. @BotFather bergan tokenni repozitoriy siriga qoʻying:",
    ", redeploy — then press Activate here.": ", qayta joylang — keyin shu yerda «Faollashtirish»ni bosing.",
    "Connected": "Ulanganlar",
