    "Broadcast": "Umumiy xabar",
    "One announcement to everyone connected — planning changes, «планёрка в 15:00».": "Barcha ulanganlarga bitta eʼlon — reja oʻzgarishlari, «планёрка в 15:00».",
    "Write the announcement…": "Eʼlonni yozing…",
    "Reminders": "Eslatmalar",
    "· send on the spot, or let them arrive on their own": "· darhol yuboring yoki oʻzi kelsin",
    "New reminder": "Yangi eslatma",
    "No reminders yet.": "Hali eslatmalar yoʻq.",
    "Delete reminder": "Eslatmani oʻchirish",
    "Name — for you, not for them": "Nomi — siz uchun, ular uchun emas",
