    // ---- Round 17 (23 Oct 2026): one vocabulary of marks ----
    "Lost files": "Egasiz fayllar",
    "for now": "hozircha",
    "Press to pick": "Kunni tanlang",
    "Every stage is one mark now — the same icon and colour on the calendar, in the task window and on My Day: a clapperboard is the shoot, scissors the edit, a palette the artwork, a tick what is out.": "Endi har bir bosqich bitta belgi — kalendarda, vazifa oynasida va «Mening kunim»da bir xil ikonka va rang: klapan — suratga olish, qaychi — montaj, palitra — dizayn, belgi — chiqdi.",
    "In a new task the days are cells: Shoot, Edit, Out. Press a cell to pick its day; Out says “Today” until you change it.": "Yangi vazifada kunlar — katakchalar: Suratga olish, Montaj, Chiqish. Kunini tanlash uchun katakchani bosing; «Chiqish» siz oʻzgartirguningizcha «Bugun» deb turadi.",
    "The task window says in one line where the piece stands, whose turn it is and the day.": "Vazifa oynasi bir qatorda material qayerda turganini, navbat kimda ekanini va kunni aytadi.",
    "In the menu: “Post Production” is now “Crew”, “Payment” is “Pay”, “Monthly notes” is “Notes”, “Unmatched files” is “Lost files”.": "Menyuda: «Post-produksiya» endi «Prodakshn», «Oylik yozuvlar» — «Eslatmalar», «Vazifasi topilmagan fayllar» — «Egasiz fayllar».",
    // ---- Round 18 (23 Oct 2026): the timeline ----
    "Who does what, and when?": "Kim nima qiladi va qachon?",
    "Every task is a line of stops — Idea, Shoot, Editing, Out — and the stop it is on is lit. The same line is on My Day, over the task window and in the new task form.": "Har bir vazifa — bekatlar chizigʻi: Gʻoya, Suratga olish, Montaj, Chiqish, — va u turgan bekat yoritilgan. Xuddi shu chiziq «Mening kunim»da, vazifa oynasi ustida va yangi vazifa shaklida.",
    "On My Day the small line in front of a title shows where the piece is; a ring in your colour is the stop that is yours.": "«Mening kunim»da nom oldidagi kichik chiziq material qayerdaligini koʻrsatadi; sizning rangingizdagi halqa — sizning bekatingiz.",
    "In a new task, When and Who are one step, Plan: press a stop on the line to give it its day and its person.": "Yangi vazifada «Qachon» va «Kim» — bitta qadam, «Reja»: bekatga kunini va odamini berish uchun chiziqdagi bekatni bosing.",
    // ---- server-errors-i18n (24 Oct 2026) ----
    "A delay belongs to production or to content — or to neither, which is the board working it out": "Kechikish prodakshn yoki kontent sababli — yoki hech biri, unda doska hali aniqlab olmoqda",
    "A skip rate is a percentage between 0 and 100, or empty for “nobody has measured it”": "Tashlab ketish foizi — 0 dan 100 gacha son, yoki boʻsh, agar «hech kim oʻlchamagan» boʻlsa",
    "A video is added by its Google Drive link": "Video Google Drive havolasi orqali qoʻshiladi",
    "Add the reference before it goes to editing — a link, a few words on how it should look, or the picture or video it should look like": "Montajga yuborishdan oldin referens qoʻshing: havola, u qanday koʻrinishi haqida bir-ikki soʻz, yoki namuna boʻladigan rasm yoki video",
    "Admins only": "Faqat adminlar uchun",
    "Answer about the shoot or the edit": "Suratga olish yoki montaj haqida javob bering",
    "Ask about a shooter, an editor or a designer": "Operator, montajchi yoki dizayner haqida soʻrang",
    "Attach the fixed file — a fix with nothing on it is the same piece coming back": "Tuzatilgan faylni biriktiring: faylsiz tuzatish — bu oʻsha materialning qaytib kelishi",
    "Campaign not found": "Kampaniya topilmadi",
    "Changes were asked for — paste the link to the new version. The one in the box is the version that was sent back.": "Tuzatish soʻralgan — yangi versiyaga havolani qoʻying. Maydondagi havola — qaytarilgan versiya.",
    "Give the day as a date": "Kunni sana koʻrinishida kiriting",
    "Give the new day as a date": "Yangi kunni sana koʻrinishida kiriting",
    "Give the task a title": "Vazifaga nom bering",
    "It is out already — TikTok and Shorts are ticked before it is published, and the reposts were made then": "Material allaqachon chiqdi: TikTok va Shorts chiqarishdan oldin belgilanadi, qayta joylashlar esa oʻshanda qilingan",
    "It would go out before it is filmed — pick the shoot day or later": "U suratga olinishidan oldin chiqib ketardi — suratga olish kunini yoki undan keyingisini tanlang",
    "Moving work out of this stage isn’t your step — see the stage rules in Admin": "Ishni bu bosqichdan koʻchirish sizning qadamingiz emas — bosqich qoidalari Admin boʻlimida",
    "Name who edits this — footage with no editor waiting is footage nobody is editing": "Kim montaj qilishini belgilang: montajchisiz xom materialni hech kim montaj qilmaydi",
    "No such stage": "Bunday bosqich yoʻq",
    "No such task": "Bunday vazifa yoʻq",
    "Not found": "Topilmadi",
    "Not your channel": "Bu sizning kanalingiz emas",
    "Nothing to bring back": "Qaytaradigan narsa yoʻq",
    "Only a delivered piece waiting at Ready can be approved": "Faqat topshirilgan va «Tekshiruvda» kutayotgan ishni qabul qilish mumkin",
    "Only a video on a channel whose videos go on to TikTok and Shorts can be reposted": "Faqat videolari TikTok va Shorts ga ham chiqadigan kanaldagi videoni qayta joylash mumkin",
    "Only admins can assign tasks to others": "Vazifani boshqalarga faqat adminlar biriktira oladi",
    "Only admins can reassign tasks": "Vazifani qayta biriktirish faqat adminlarga mumkin",
    "Only an admin answers a date request": "Sana soʻroviga faqat admin javob beradi",
    "Only an admin on this channel decides whose delay it was": "Kechikish kimdan boʻlganini faqat bu kanal admini hal qiladi",
    "Only an admin on this channel, or somebody the piece is for, records its skip rate": "Tashlab ketish foizini faqat bu kanal admini yoki material kim uchun boʻlsa, oʻsha kiritadi",
    "Only an admin on this channel, or somebody the piece is for, records its views": "Koʻrishlarni faqat bu kanal admini yoki material kim uchun boʻlsa, oʻsha kiritadi",
    "Only somebody on this task can raise a hand about it": "Vazifa boʻyicha qoʻl koʻtarishni faqat unda qatnashayotgan odam qila oladi",
    "Only the assignee can edit this checklist": "Bu roʻyxatni faqat ijrochi oʻzgartira oladi",
    "Only the channel’s reviewer can approve the edit": "Montajni faqat kanal tekshiruvchisi qabul qila oladi",
