    "Only whoever runs this piece, or an admin on its channel, says where else it goes": "Material yana qayerga chiqishini faqat uni yurituvchi yoki uning kanali admini hal qiladi",
    "Paste the link to your footage, or the name of the file": "Xom materialingizga havolani yoki fayl nomini qoʻying",
    "Pick 7, 14 or 30 days, or off": "7, 14 yoki 30 kunni tanlang — yoki oʻchiring",
    "Pick a channel whose videos are edited": "Videolari montaj qilinadigan kanalni tanlang",
    "Pick a person from the list": "Roʻyxatdan odamni tanlang",
    "Pick at least one platform": "Kamida bitta platformani tanlang",
    "Pick one of the ten colours": "Oʻnta rangdan birini tanlang",
    "Pick the day to post — the edit is made for a day, and the editor works back from it": "Chiqish kunini tanlang: montaj kunga qarab qilinadi, montajchi undan orqaga hisoblaydi",
    "Pick the hour as well — their week is right there, and a shoot day with no time is a day nobody can plan around": "Soatni ham tanlang: operatorning haftasi shu yerda, vaqtsiz suratga olish kuniga esa hech kim moslasha olmaydi",
    "Pick the new day": "Yangi kunni tanlang",
    "Pick the shoot day — a shoot with no day is one nobody can turn up to": "Suratga olish kunini tanlang: kunsiz suratga olishga hech kim kelmaydi",
    "Pick who is filming this — a shoot nobody is holding is nobody’s job": "Kim suratga olishini tanlang: operatorsiz suratga olish — hech kimning ishi emas",
    "Say what happened — a day moves on a reason, and “—” is not one": "Nima boʻlganini yozing: kun sabab bilan koʻchiriladi, «—» esa sabab emas",
    "Say what is in the way — a heads-up with no reason leaves the same guessing as no heads-up": "Nima xalaqit berayotganini yozing: sababsiz ogohlantirish ham ogohlantirish boʻlmagandek taxminda qoldiradi",
    "Say what is in the way — a no with no reason cannot be planned around": "Nima xalaqit qilayotganini yozing — sababsiz rad javobini rejaga kiritib boʻlmaydi",
    "Say why — a verdict nobody can read back is worse than the board’s guess": "Nega ekanini yozing: hech kim qayta oʻqiy olmaydigan qaror doskaning taxminidan ham yomon",
    "Suggest a day, or hand the task back": "Kun taklif qiling yoki vazifani qaytaring",
    "That day already has a request waiting on an admin": "Bu kun boʻyicha adminni kutayotgan soʻrov allaqachon bor",
    "That day belongs to a channel you don’t run — its own admin answers this": "Bu kun siz yuritmaydigan kanalga tegishli — bunga uning oʻz admini javob beradi",
    "That day has changed since the request was made — ask again against the day it has now": "Soʻrovdan keyin bu kun oʻzgargan — hozir turgan kun boʻyicha qayta soʻrang",
