    "You can see the stage but can’t move it — use your Shot / Edited tick, or ask an admin": "Bosqichni koʻrasiz, lekin koʻchira olmaysiz — «Suratga oldim» / «Montaj qildim» belgisini qoʻying yoki admindan soʻrang",
