    // ---- news-i18n (24 Oct 2026) ----
    "A step with nobody on it is on your day now: an admin sees “Nobody holds these” first on My Day; a maker’s piece sent on with no editor, operator or designer is under “Your move”, and the task window names the person in one press.": "Odamsiz qadam endi sizning kuningizda: admin «Mening kunim»da birinchi boʻlib «Hech kimning qoʻlida emas»ni koʻradi; montajchisiz, operatorsiz yoki dizaynersiz joʻnatilgan material «Sizning navbatingiz»da, vazifa oynasi esa odamni bir bosishda belgilaydi.",
    "Days keep their order: a piece cannot go out before it is filmed or edited, and an edit is not due before the shoot. A new task with no day lands on today, and one with no owner belongs to whoever made it.": "Kunlar tartibda: material suratga olinishidan yoki montajdan oldin chiqa olmaydi, montaj muddati esa suratga olishdan oldin boʻlmaydi. Kunsiz yangi vazifa bugunga tushadi, yurituvchisiz vazifa esa uni yaratganda qoladi.",
    "What the board refuses, it now says in your language.": "Doska rad etgan narsani endi sizning tilingizda aytadi.",
    "The counts beside the channels and your day refresh right after a move, and whoever is replaced on a task is told.": "Kanallar yonidagi sonlar va sizning kuningiz harakatdan keyin darhol yangilanadi, vazifadan olingan odamga esa xabar boradi.",
    // ---- drive-i18n (24 Oct 2026) ----
