    "Connected — new work, pravkas, work to review and @-mentions land in Telegram, with buttons to answer there.": "Ulandi — yangi ish, tahrirlar, tekshiruvga ish va @ bilan belgilashlar Telegramga keladi, javob berish tugmalari bilan.",
    "Only what you have to act on: new work, a pravka, work to review, an @-mention. Quiet from 23:00 to 08:00.": "Faqat siz bajarishingiz kerak boʻlgan narsalar: yangi ish, tahrir, tekshiruvga ish, @ bilan belgilash. 23:00 dan 08:00 gacha jimlik.",
