    "in no menu since 20 October; the page and its backlog stay by their address until 3 November": "20-oktabrdan menyuda yoʻq; sahifa va uning bekloqi 3-noyabrgacha manzili orqali ochiladi",
    "Sprints has left the menu and retires on 3 November. The ideas from its backlog are kept in Settings → Records.": "Sprintlar menyudan chiqdi va 3-noyabrda yopiladi. Bekloqdagi gʻoyalar Sozlamalar → Yozuvlar boʻlimida saqlanadi.",
