    "Numbers is one page: Month, People and Pay are three buttons at the top. Your own pay is under your profile.": "Raqamlar — bitta sahifa: Oy, Odamlar va Toʻlov — tepadagi uchta tugma. Sizning toʻlovingiz profilingizda.",
