    "Team is one page: People, Workload and Access are three buttons at the top. Hiring and Candidates are gone.": "Jamoa — bitta sahifa: Odamlar, Ish yuki va Kirish huquqi — tepadagi uchta tugma. Ishga olish va nomzodlar olib tashlandi.",
