    "Records": "Yozuvlar",
    "Settings has four tabs — Board, Team, Integrations, Records — and nothing under “More”. Every page of the old Admin panel is on one of them.": "Sozlamalarda toʻrtta boʻlim — Doska, Jamoa, Integratsiyalar, Yozuvlar — va «Yana» ostida hech narsa yoʻq. Eski admin panelining har bir sahifasi ulardan birida.",
    "“What changed” lives in the bell now, with a badge until you open it. My Day starts with your card.": "«Nima oʻzgardi» endi qoʻngʻiroqchada, siz uni ochmaguningizcha belgi bilan. «Mening kunim» sizning kartochkangizdan boshlanadi.",
