    "Edit opens the same form a new task uses, at the step you pressed; Save writes that step and nothing else. The full sheet is behind “All fields”.": "«Oʻzgartirish» yangi vazifa ishlatadigan shaklni, siz bosgan qadamda ochadi; «Saqlash» faqat shu qadamni yozadi. Toʻliq varaq — «Barcha maydonlar» tugmasi ortida.",
